const payload = msg.payload;
if (!payload || typeof payload !== 'object') return null;
const { temp, hum } = payload;
if (typeof temp !== 'number' || typeof hum !== 'number') return null;
if (!Number.isFinite(temp) || !Number.isFinite(hum)) return null;
if (temp < -40 || temp > 80 || hum < 0 || hum > 100) return null;

msg.payload = { temp, hum, ts: new Date().toISOString() };
return msg;

const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
  node.warn('Missing SUPABASE_URL or SUPABASE_KEY env var');
  return null;
}
msg.url = `${url}/rest/v1/sensor_data`;
msg.headers = {
  apikey: key,
  Authorization: `Bearer ${key}`,
  'Content-Type': 'application/json',
  Prefer: 'return=minimal'
};
msg.payload = {
  temp: msg.payload.temp,
  hum: msg.payload.hum
};
return msg;

const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
  node.warn('Missing SUPABASE_URL or SUPABASE_KEY env var');
  return null;
}
const since = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
msg.url = `${url}/rest/v1/sensor_data?select=temp,hum,created_at&created_at=gte.${encodeURIComponent(since)}&order=created_at.asc`;
msg.headers = {
  apikey: key,
  Authorization: `Bearer ${key}`
};
return msg;

const rows = msg.payload;
const round1 = (v) => Math.round(v * 10) / 10;

if (!Array.isArray(rows) || rows.length === 0) {
  return [
    { payload: [] },
    { payload: { avgTemp: 0, minTemp: 0, maxTemp: 0, avgHum: 0, count: 0 } }
  ];
}

let sumTemp = 0, sumHum = 0, minTemp = Infinity, maxTemp = -Infinity;
const tempPoints = [], humPoints = [];

for (const r of rows) {
  sumTemp += r.temp;
  sumHum += r.hum;
  if (r.temp < minTemp) minTemp = r.temp;
  if (r.temp > maxTemp) maxTemp = r.temp;
  tempPoints.push({ series: 'Nhiệt độ (°C)', x: r.created_at, y: r.temp });
  humPoints.push({ series: 'Độ ẩm (%)', x: r.created_at, y: r.hum });
}

return [
  { payload: [...tempPoints, ...humPoints] },
  {
    payload: {
      avgTemp: round1(sumTemp / rows.length),
      minTemp: round1(minTemp),
      maxTemp: round1(maxTemp),
      avgHum: round1(sumHum / rows.length),
      count: rows.length
    }
  }
];

const url = env.get('SUPABASE_URL');
const key = env.get('SUPABASE_KEY');
if (!url || !key) {
  node.warn('Missing SUPABASE_URL or SUPABASE_KEY env var');
  return null;
}
msg.url = `${url}/rest/v1/study_sessions?select=duration_min,target_min,rating,avg_temp,avg_hum,started_at&order=started_at.desc&limit=200`;
msg.headers = {
  apikey: key,
  Authorization: `Bearer ${key}`
};
return msg;

const sessions = msg.payload;
const valid = Array.isArray(sessions)
  ? sessions.filter(
      (s) =>
        typeof s.duration_min === 'number' &&
        typeof s.rating === 'number' &&
        typeof s.avg_temp === 'number' &&
        typeof s.avg_hum === 'number' &&
        s.started_at
    )
  : [];

if (valid.length < 5) {
  msg.payload = {
    coldStart: true,
    sampleCount: valid.length,
    optimal: null,
    recommendation: 'Chưa đủ dữ liệu phiên học (cần tối thiểu 5 phiên). Khuyến nghị mặc định: 24–27°C, độ ẩm 50–65%.'
  };
  return msg;
}

function bestBin(map) {
  let bestKey = null, bestAvg = -1;
  for (const [key, entry] of map.entries()) {
    const avg = entry.sum / entry.count;
    if (avg > bestAvg) { bestAvg = avg; bestKey = key; }
  }
  return bestKey;
}

const tempBins = new Map(), humBins = new Map(), hourBins = new Map();
for (const s of valid) {
  const target = s.target_min > 0 ? s.target_min : 25;
  const completion = Math.min(1, s.duration_min / target);
  const q = 0.5 * completion + 0.5 * (s.rating / 5);
  const tLow = Math.floor(s.avg_temp / 2) * 2;
  const hLow = Math.floor(s.avg_hum / 10) * 10;
  const hrLow = Math.floor(new Date(s.started_at).getUTCHours() / 2) * 2;
  const add = (map, key) => {
    const cur = map.get(key) || { sum: 0, count: 0 };
    cur.sum += q;
    cur.count += 1;
    map.set(key, cur);
  };
  add(tempBins, `${tLow}-${tLow + 2}`);
  add(humBins, `${hLow}-${hLow + 10}`);
  const pad = (n) => String(n).padStart(2, '0');
  add(hourBins, `${pad(hrLow)}:00-${pad(hrLow + 2)}:00`);
}

const tempRange = bestBin(tempBins).split('-').map(Number);
const humRange = bestBin(humBins).split('-').map(Number);
const bestHour = bestBin(hourBins);

msg.payload = {
  coldStart: false,
  sampleCount: valid.length,
  optimal: { tempRange, humRange, bestHour },
  recommendation: `Điều kiện tối ưu của bạn: ${tempRange[0]}–${tempRange[1]}°C, độ ẩm ${humRange[0]}–${humRange[1]}%, khung giờ vàng ${bestHour}.`
};
return msg;
